"""Minimal i18n: English source strings → Hebrew. `tr(s)` returns the
translation when the active language is Hebrew, otherwise `s` unchanged;
`trf(template, **kw)` translates a template and then formats it.

The console's own UI text lives here. Catalog prose (test titles, purposes,
steps, preconditions, safety plans, phase names) is translated by the catalog
overlay `catalog/DVT_test_catalog.<lang>.yaml`, applied by `Catalog.load(path,
lang)` — so in Hebrew everything the operator reads is Hebrew, in English
everything is English (SRS-DVT-194). Identifiers (test ids, field names, enum
values, verdicts PASS/FAIL/BLOCKED/WAIVED, pass_criteria) are never translated.
"""

from __future__ import annotations

LANG = "en"           # "en" | "he"
LANGUAGES = {"en": "English", "he": "עברית"}


def set_language(code: str) -> None:
    global LANG
    LANG = code if code in LANGUAGES else "en"


def is_rtl() -> bool:
    return LANG == "he"


def tr(s: str) -> str:
    if LANG == "he":
        return HE.get(s, s)
    return s


def trf(template: str, **kw) -> str:
    """tr() for messages with placeholders: trf("Next: {test}", test=tid)."""
    return tr(template).format(**kw)


